#include <algorithm>
using namespace std;

#define ll long long
const ll INF = 1 << 30;

ll n, k;
ll ara[200005], dp[200005];

int main() {
    scanf("%lld %lld", &n, &k);
    memset(dp, -1, sizeof dp); // Using memset for better performance
    for (ll i = 1; i <= n; i++) {
        scanf("%lld", &ara[i]);
    }

    // Iterative approach to calculate minimum costs
    dp[n] = 0; // Base case
    for (int pos = n - 1; pos >= 1; pos--) {
        dp[pos] = abs(ara[pos + 1] - ara[pos]) + dp[pos + 1];
        for (int i = 2; i <= k && pos + i <= n; i++) {
            dp[pos] = min(abs(ara[pos] - ara[pos + i]) + dp[pos + i], dp[pos]);
        }
    }

    printf("%lld\n", dp[1]);
    return 0;
}

